"""
NAVIGATIE-HERSTRUCTURERING -- STAP B3 (LAATSTE STAP): e-maillinks in de
4 externe batch-scripts bijgewerkt naar de nieuwe URL-structuur.

Dit is het allerlaatste stukje van de navigatie-herstructurering (Stap
A + B1 + B2 waren al klaar) -- de site zelf gebruikte al maanden geen
'?view=X'-links meer, maar deze 4 EXTERNE scripts (die los van de app
draaien via GitHub Actions) hadden nog de oude URL's in hun uitgaande
e-mails staan.

Bijgewerkt:
1. weekly_batch.py: Discover-link (1x)
2. portfolio_watch.py: Analyze > Portfolio Overview-link (1x)
3. screener_daily.py: Discover/Today/Analyze-links (5x, verdeeld over
   de 'geen signalen'- en 'wel signalen'-e-mailvarianten)
4. daily_email_dispatch.py: uitschrijf-link (1x)

Totaal 8 links bijgewerkt, allemaal van '?view=X(&subview=Y)' naar
'/X(?subview=Y)'.

Grondig getest: alle 4 bestanden syntactisch gecontroleerd, alle URL's
string-matched op aanwezigheid, en de 2 e-mailfuncties in
screener_daily.py DAADWERKELIJK aangeroepen met echte testdata om de
gerenderde HTML te controleren (niet alleen de brontekst).

Gebruik: python fix_email_links_step_b3.py
Draai dit vanuit je stock_screener-map (hestys-fresh).
"""

WEEKLY_BATCH_CONTENT = b'"""\nWekelijks batch-script: draait de gedeelde screener EN stuurt elke\ngeregistreerde gebruiker een persoonlijke e-mail over hun eigen portfolio.\n\nBedoeld om te draaien via GitHub Actions (dus GEEN Streamlit-context --\nleest configuratie via omgevingsvariabelen, niet via st.secrets zoals\nhet dashboard zelf doet).\n\nBenodigde omgevingsvariabelen (als GitHub Actions secrets, of lokaal in .env):\n  SUPABASE_URL, SUPABASE_ANON_KEY\n  EMAIL_SMTP_SERVER, EMAIL_SMTP_PORT, EMAIL_ADDRESS, EMAIL_APP_PASSWORD\n\nGebruik: python weekly_batch.py\n"""\nfrom __future__ import annotations\n\nimport os\n\nimport pandas as pd\nfrom dotenv import load_dotenv\nfrom supabase import create_client\n\nload_dotenv()\n\nimport screener\nfrom portfolio_watch import check_holding, build_email_body\nfrom database import get_roic_trend_history, save_roic_trend_history\nfrom emailer import send_email\n\n\ndef get_supabase_client():\n    url = os.environ["SUPABASE_URL"]\n    key = os.environ["SUPABASE_ANON_KEY"]\n    return create_client(url, key)\n\n\ndef get_real_email(email_hash: str) -> str:\n    """\n    Zoekt het echte, verstuurbare e-mailadres op bij een hash -- nodig\n    omdat portfolio_holdings/user_preferences alleen de hash kennen, niet\n    het leesbare adres zelf (zie database.py\'s module-docstring).\n    """\n    client = get_supabase_client()\n    response = client.table("user_identity").select("email").eq("email_hash", email_hash).execute()\n    if response.data:\n        return response.data[0]["email"]\n    return None\n\n\ndef get_all_users_with_holdings() -> dict:\n    """\n    Geeft alle gebruikers en hun ACTIEVE, EIGEN posities terug, gegroepeerd\n    per (gehasht) e-mailadres. Filtert expliciet op is_watchlist=false EN\n    shares > 0 -- zonder deze filters kwamen watchlist-items en al-\n    verkochte posities (shares=0, blijven soms als rij staan i.p.v.\n    verwijderd) ook mee in de Portfolio Watch-mail, wat precies de bron\n    was van \'ik krijg info over posities die ik al verkocht heb\'.\n    """\n    client = get_supabase_client()\n    response = (\n        client.table("portfolio_holdings")\n        .select("*")\n        .eq("is_watchlist", False)\n        .gt("shares", 0)\n        .execute()\n    )\n\n    grouped: dict[str, list[dict]] = {}\n    for row in response.data:\n        grouped.setdefault(row["user_email"], []).append(row)\n    return grouped\n\n\ndef get_all_preferences() -> dict:\n    """Geeft de e-mail-voorkeuren van ALLE gebruikers terug (sleutel = gehasht e-mailadres)."""\n    client = get_supabase_client()\n    response = client.table("user_preferences").select("*").execute()\n    return {row["user_email"]: row for row in response.data}\n\n\ndef run_screener_shared() -> None:\n    """\n    Draait de gedeelde screener 1x -- de resultaten (CSV\'s, incl. Snowball\n    Signal en Rocket List) zijn voor iedereen zichtbaar op de website.\n    send_own_email=False, want de vaste mail naar het eigen GitHub-\n    secrets-adres zou dubbel op kunnen tellen met de per-gebruiker-opt-in-\n    mail hieronder (run_weekly_signals_emails) als dat hetzelfde adres is.\n    """\n    print("=== Gedeelde screener draaien (publiek, voor iedereen zichtbaar) ===")\n    screener.main(send_own_email=False)\n\n\ndef _format_momentocrats_row(row) -> str:\n    return (f"[score {row[\'score\']}] {row[\'ticker\']}: flipped {row[\'weken_geleden\']} week(en) ago "\n            f"({row[\'sinds_omslag_pct\']:+.2f}% since)")\n\n\ndef _format_snowball_row(row) -> str:\n    return (f"{row[\'ticker\']}: ROIC {row[\'roic_pct\']:.1f}%, "\n            f"{row[\'afwijking_fair_value_pct\']:+.1f}% vs. fair value")\n\n\ndef _format_rocket_row(row) -> str:\n    return (f"{row[\'ticker\']}: {row[\'groei_pct\']:.1f}% growth, "\n            f"{row[\'relatieve_sterkte\']:+.1f}% relative strength")\n\n\nSIGNAL_TYPES = {\n    "momentocrats": {\n        "pref_key": "wants_momentocrats_email", "csv": "supertrend_signals.csv",\n        "title": "Momentocrats", "emoji": "\xf0\x9f\x93\xa1", "sort_by": "score", "sort_asc": False,\n        "formatter": _format_momentocrats_row,\n    },\n    "snowball": {\n        "pref_key": "wants_snowball_email", "csv": "snowball_signals.csv",\n        "title": "Snowballers", "emoji": "\xf0\x9f\x90\xa6", "sort_by": "afwijking_fair_value_pct", "sort_asc": True,\n        "formatter": _format_snowball_row,\n    },\n    "rocket": {\n        "pref_key": "wants_rocket_email", "csv": "rocket_list_signals.csv",\n        "title": "Rocket List", "emoji": "\xf0\x9f\x9a\x80", "sort_by": "groei_pct", "sort_asc": False,\n        "formatter": _format_rocket_row,\n    },\n}\n\n\ndef build_weekly_signals_email(sections: list, is_premium: bool = False, daily_flips_text: str = "", daily_flips_html: str = "") -> tuple:\n    """\n    Bouwt 1 gecombineerde mail voor alle signaal-types die deze gebruiker\n    heeft aangevinkt, plus (optioneel) vrijdag\'s dagelijkse flips.\n\n    Toont altijd top 3 per signaal, OOK voor premium -- een mail met\n    tientallen regels per signaal is geen prettige samenvatting meer,\n    dat is precies waar Discover (met een scrollbare tabel) voor is.\n    De \'is_premium\'-parameter blijft bestaan voor later (zodra premium\n    functioneel is), maar be\xc3\xafnvloedt de mail-inhoud nu bewust niet.\n\n    sections: lijst van dicts met keys \'title\', \'emoji\', \'df\', \'formatter\'.\n    daily_flips_text/daily_flips_html: optioneel, van build_daily_flips_section() --\n    leeg als er niks te melden was (dan wordt deze sectie gewoon overgeslagen).\n    """\n    display_limit = 3\n    text_lines = ["Good morning from Hesty\'s -- your weekly signals are in.", ""]\n    html_sections_list = []\n\n    for section in sections:\n        total_this_section = len(section["df"])\n        top_n = section["df"].head(display_limit)\n        text_lines.append(f"{section[\'emoji\']} {section[\'title\']} (top {len(top_n)} of {total_this_section} total):")\n        for _, row in top_n.iterrows():\n            text_lines.append(f"  - {section[\'formatter\'](row)}")\n        text_lines.append("")\n\n        rows_html = "".join(\n            f"<li style=\'padding:4px 0;color:#101825;\'>{section[\'formatter\'](row)}</li>"\n            for _, row in top_n.iterrows()\n        )\n        html_sections_list.append(f"""\n        <h4 style="color:#101825; font-size:16px; margin:20px 0 8px 0;">{section[\'emoji\']} {section[\'title\']}</h4>\n        <ul style="margin:0; padding-left:20px; font-size:14px;">{rows_html}</ul>\n        """)\n\n    if daily_flips_text:\n        text_lines.append(daily_flips_text)\n    if daily_flips_html:\n        html_sections_list.append(daily_flips_html)\n\n    text_lines += [\n        "See the full lists, sector rotation, and top movers under Discover on the site.",\n        "",\n        "-- Hesty\'s, your personal investment assistant",\n        "",\n        "This is a screener, not investment advice.",\n    ]\n    text_body = "\\n".join(text_lines)\n\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Weekly</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">Your weekly signals are in</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            {\'\'.join(html_sections_list)}\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\n                See the full lists, sector rotation, and top movers under\n                <a href="https://hestys.streamlit.app/discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a> on the site.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef run_weekly_signals_emails(preferences: dict, daily_flips_text: str = "", daily_flips_html: str = "") -> None:\n    """\n    Stuurt 1 gecombineerde mail per gebruiker, met alleen de signaal-types\n    waar diegene zich voor heeft aangemeld (top 3 gratis / top 10 premium),\n    plus (optioneel) vrijdag\'s dagelijkse flips erbij.\n\n    daily_flips_text/daily_flips_html: alleen toegevoegd aan mails die\n    sowieso al verstuurd worden (dus gebruikers met minstens 1 signaal-\n    type aangevinkt) -- geen nieuwe categorie gebruikers die anders\n    niks zouden ontvangen.\n    """\n    print("\\n=== Wekelijkse signalen-mails versturen aan opt-in-gebruikers ===")\n\n    # Laad elke CSV maar 1x, niet per gebruiker opnieuw\n    csv_cache = {}\n    for key, config in SIGNAL_TYPES.items():\n        if os.path.exists(config["csv"]):\n            df = pd.read_csv(config["csv"])\n            if not df.empty:\n                df = df.sort_values(config["sort_by"], ascending=config["sort_asc"])\n                csv_cache[key] = df\n\n    for user_email_hash, prefs in preferences.items():\n        sections = []\n        for key, config in SIGNAL_TYPES.items():\n            if not prefs.get(config["pref_key"]):\n                continue\n            if key not in csv_cache:\n                continue\n            sections.append({\n                "title": config["title"], "emoji": config["emoji"],\n                "df": csv_cache[key], "formatter": config["formatter"],\n            })\n\n        if not sections:\n            continue\n\n        real_email = get_real_email(user_email_hash)\n        if not real_email:\n            print(f"  Kon geen e-mailadres vinden voor hash {user_email_hash[:12]}... -- overgeslagen.")\n            continue\n\n        is_premium = bool(prefs.get("is_premium", False))\n        print(f"  {real_email} ({\'premium\' if is_premium else \'free\'}): {\', \'.join(s[\'title\'] for s in sections)}")\n        text_body, html_body = build_weekly_signals_email(\n            sections, is_premium=is_premium,\n            daily_flips_text=daily_flips_text, daily_flips_html=daily_flips_html,\n        )\n        total_signals = sum(len(s["df"]) for s in sections)\n        subject = f"Hesty\'s Weekly: {total_signals} new signal(s) this week"\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=real_email)\n\n\ndef run_portfolio_emails(preferences: dict) -> None:\n    """\n    Checkt en mailt elke geregistreerde gebruiker zijn eigen, persoonlijke\n    portfolio -- behalve als hij dat expliciet heeft uitgezet. Standaard AAN\n    (ook voor gebruikers die nog nooit hun voorkeuren hebben aangepast).\n    """\n    print("\\n=== Persoonlijke portfolio-e-mails versturen ===")\n    users = get_all_users_with_holdings()\n    print(f"{len(users)} gebruiker(s) gevonden met een portfolio.")\n\n    for user_email_hash, holdings in users.items():\n        user_prefs = preferences.get(user_email_hash, {})\n        if not user_prefs.get("wants_portfolio_email", True):\n            print(f"\\n--- {user_email_hash[:12]}...: heeft de portfolio-mail uitgezet, overgeslagen ---")\n            continue\n\n        real_email = get_real_email(user_email_hash)\n        if not real_email:\n            print(f"\\n--- {user_email_hash[:12]}...: geen e-mailadres gevonden, overgeslagen ---")\n            continue\n\n        print(f"\\n--- {real_email} ({len(holdings)} positie(s)) ---")\n        results = []\n        for holding in holdings:\n            result = check_holding(holding["naam"], holding["ticker"])\n            if result:\n                result["shares"] = holding.get("shares")\n                results.append(result)\n\n        if not results:\n            print("  Geen van de posities kon gecheckt worden -- geen mail verstuurd.")\n            continue\n\n        df = pd.DataFrame(results)\n\n        # Alleen NIEUWE signalen laten meetellen -- zelfde logica als\n        # portfolio_watch.py\'s eigen main().\n        previous_states = get_roic_trend_history(df["ticker"].tolist())\n\n        def _was_roic_trend(ticker, trend):\n            return previous_states.get(ticker, {}).get("roic_trend") == trend\n\n        def _was_fair_value_bucket(ticker, bucket):\n            return previous_states.get(ticker, {}).get("fair_value_bucket") == bucket\n\n        df["roic_decline_is_new"] = df.apply(\n            lambda r: r["roic_trend"] == "dalend" and not _was_roic_trend(r["ticker"], "dalend"), axis=1\n        )\n        df["roic_improvement_is_new"] = df.apply(\n            lambda r: r["roic_trend"] == "stijgend" and not _was_roic_trend(r["ticker"], "stijgend"), axis=1\n        )\n        df["fair_value_crossed_expensive_is_new"] = df.apply(\n            lambda r: r["fair_value_bucket"] == "expensive" and not _was_fair_value_bucket(r["ticker"], "expensive"), axis=1\n        )\n        df["fair_value_crossed_cheap_is_new"] = df.apply(\n            lambda r: r["fair_value_bucket"] == "cheap" and not _was_fair_value_bucket(r["ticker"], "cheap"), axis=1\n        )\n\n        text_body, html_body = build_email_body(df)\n        n_changed = int(df["recent_gewijzigd"].sum())\n        n_earnings = int((df["earnings_surprise_pct"].notna()).sum())\n        subject_parts = []\n        if n_changed > 0:\n            subject_parts.append(f"{n_changed} trend change(s)")\n        if n_earnings > 0:\n            subject_parts.append(f"{n_earnings} earnings update(s)")\n        subject = f"Portfolio Watch: {\', \'.join(subject_parts)}" if subject_parts else "Portfolio Watch: no notable changes this week"\n\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=real_email)\n\n        # De HUIDIGE stand opslaan als \'vorige week\' voor de volgende run\n        # -- onafhankelijk per ticker (niet per gebruiker), aangezien deze\n        # waardes voor iedereen hetzelfde zijn.\n        current_states = {\n            row["ticker"]: {"roic_trend": row["roic_trend"], "fair_value_bucket": row["fair_value_bucket"]}\n            for _, row in df.iterrows()\n        }\n        save_roic_trend_history(current_states)\n\n\ndef run_daily_flip_scan_for_weekly() -> None:\n    """\n    Draait de dagelijkse flip-scan OPNIEUW, specifiek voor de zaterdag-\n    weekly-mail -- dit vangt de VOLLEDIGE, net-afgeronde vrijdag-sessie op.\n    (De reguliere vrijdagochtend-scan draaide namelijk vroeg, VOORDAT de\n    Amerikaanse beurs zelfs maar open was, en liet dus donderdag-vs-\n    woensdag\'s beweging zien, niet de volledige vrijdag-sessie.)\n\n    Schrijft dezelfde bestanden als de dagelijkse scan (supertrend_signals_daily.csv,\n    top_movers.csv) -- verstuurt zelf GEEN aparte mail, de resultaten worden\n    hieronder in de weekly-mail verwerkt.\n    """\n    import screener_daily\n    print("\\n=== Dagelijkse flip-scan opnieuw draaien (voor de volledige vrijdag-sessie) ===")\n    screener_daily.main(send_own_email=False)\n\n\ndef build_daily_flips_section() -> tuple:\n    """\n    Bouwt een tekst- en HTML-fragment met de belangrijkste flips uit de\n    zojuist opnieuw gedraaide dagelijkse scan (dus: vrijdag\'s volledige\n    sessie) -- toegevoegd aan de zaterdag-weekly-mail, i.p.v. hiervoor een\n    aparte mail te sturen. Geeft (leeg, leeg) terug als er geen data is\n    of geen signalen waren, zodat de aanroeper deze sectie dan gewoon\n    kan overslaan.\n    """\n    if not os.path.exists("supertrend_signals_daily.csv"):\n        return "", ""\n    df_daily = pd.read_csv("supertrend_signals_daily.csv")\n    if df_daily.empty:\n        return "", ""\n\n    df_daily = df_daily.sort_values("score", ascending=False)\n    display_limit = 5\n    top_n = df_daily.head(display_limit)\n\n    text_lines = [f"\xf0\x9f\x93\x85 Friday\'s daily flips (top {len(top_n)} of {len(df_daily)} total):"]\n    for _, row in top_n.iterrows():\n        text_lines.append(\n            f"  - [{row[\'score\']}] {row[\'ticker\']}: {row[\'prijs_bij_omslag\']} -> {row[\'prijs_nu\']} "\n            f"({row[\'sinds_omslag_pct\']:+.2f}%)"\n        )\n    text_lines.append("")\n    text_fragment = "\\n".join(text_lines)\n\n    rows_html = "".join(\n        f"<li style=\'padding:4px 0;color:#101825;\'>[{row[\'score\']}] {row[\'ticker\']}: "\n        f"{row[\'prijs_bij_omslag\']} &rarr; {row[\'prijs_nu\']} ({row[\'sinds_omslag_pct\']:+.2f}%)</li>"\n        for _, row in top_n.iterrows()\n    )\n    html_fragment = f"""\n    <h4 style="color:#101825; font-size:16px; margin:20px 0 8px 0;">\xf0\x9f\x93\x85 Friday\'s daily flips (top {len(top_n)} of {len(df_daily)} total)</h4>\n    <ul style="margin:0; padding-left:20px; font-size:14px;">{rows_html}</ul>\n    """\n    return text_fragment, html_fragment\n\n\ndef run_saturday() -> None:\n    """\n    Zaterdag: de gedeelde screener + wekelijkse signalen-mails (Momentocrats/\n    Snowballers/Rocket List) -- nu AANGEVULD met vrijdag\'s volledige\n    dagelijkse flips (i.p.v. daarvoor een aparte mail te sturen). Portfolio\n    Watch is BEWUST verplaatst naar zondag (zie run_sunday) -- anders kreeg\n    je 2-3 mails tegelijk op zaterdagochtend.\n    """\n    run_screener_shared()\n    run_daily_flip_scan_for_weekly()\n    all_preferences = get_all_preferences()\n    daily_flips_text, daily_flips_html = build_daily_flips_section()\n    run_weekly_signals_emails(all_preferences, daily_flips_text=daily_flips_text, daily_flips_html=daily_flips_html)\n\n\ndef run_sunday() -> None:\n    """Zondag: alleen Portfolio Watch -- apart van de zaterdag-signalen, geen mail-opeenstapeling meer."""\n    all_preferences = get_all_preferences()\n    run_portfolio_emails(all_preferences)\n\n\nif __name__ == "__main__":\n    import sys\n    mode = sys.argv[1] if len(sys.argv) > 1 else "saturday"\n    if mode == "saturday":\n        run_saturday()\n    elif mode == "sunday":\n        run_sunday()\n    else:\n        raise ValueError(f"Onbekende modus: \'{mode}\' -- gebruik \'saturday\' of \'sunday\'.")\n    print("\\nKlaar.")\n'

PORTFOLIO_WATCH_CONTENT = b'"""\r\nPortfolio Watch: volgt de HUIDIGE Supertrend-status van je eigen bestaande\r\nposities (in tegenstelling tot screener.py, dat naar NIEUWE idee\xc3\xabn in\r\nAEX/Nasdaq-100 zoekt). Dit is vooral relevant bij een geconcentreerde\r\nportfolio -- weten of je grootste positie (bv. Tesla) nog steeds in een\r\nbullish trend zit, is vaak belangrijker dan een willekeurig nieuw signaal.\r\n\r\nHaalt je posities nu RECHTSTREEKS uit de database (dezelfde die \'My\r\nPortfolio\' op de site gebruikt), i.p.v. een hardgecodeerde lijst die\r\nhandmatig bijgewerkt moest worden -- deze mail blijft nu altijd\r\ngesynchroniseerd met wat je daadwerkelijk bezit, ook als je iets koopt\r\nof verkoopt. Alleen posities met shares > 0 worden meegenomen (geen\r\nwatchlist-items, geen posities die je al verkocht hebt).\r\n\r\nVereist: pip install -r requirements.txt\r\nVereist env-var: PORTFOLIO_WATCH_USER_EMAIL (welk account de posities gevolgd worden)\r\n\r\nGebruik: python portfolio_watch.py\r\n"""\r\nfrom __future__ import annotations\r\n\r\nimport os\r\n\r\nimport pandas as pd\r\nimport yfinance as yf\r\n\r\nfrom indicators import supertrend, ema, resample_to_weekly\r\nfrom screener import get_roic_data, fetch_weekly, get_earnings_surprise, get_fair_value_estimate\r\nfrom emailer import send_email, is_configured as email_is_configured\r\nfrom database import get_user_holdings, get_roic_trend_history, save_roic_trend_history\r\n\r\n\r\ndef get_current_holdings() -> list:\r\n    """\r\n    Haalt de ACTUELE, eigen posities op uit de database (i.p.v. een\r\n    hardgecodeerde lijst) -- alleen posities met shares > 0 (geen\r\n    watchlist-items, geen verkochte posities). Vereist de env-var\r\n    PORTFOLIO_WATCH_USER_EMAIL, zodat dit script weet WELK account\r\n    gevolgd moet worden (het draait immers los van een ingelogde sessie).\r\n    """\r\n    user_email = os.getenv("PORTFOLIO_WATCH_USER_EMAIL")\r\n    if not user_email:\r\n        raise ValueError(\r\n            "PORTFOLIO_WATCH_USER_EMAIL is niet ingesteld -- Portfolio Watch weet "\r\n            "hierdoor niet welk account de posities gevolgd moeten worden."\r\n        )\r\n    all_holdings = get_user_holdings(user_email, is_watchlist=False)\r\n    return [\r\n        {"naam": h["naam"], "ticker": h["ticker"], "shares": h["shares"]}\r\n        for h in all_holdings\r\n        if (h.get("shares") or 0) > 0\r\n    ]\r\n\r\nATR_LENGTH = 6\r\nATR_MULTIPLIER = 2.6\r\nTREND_FILTER_EMA_LENGTH = 20\r\nRECENT_CHANGE_WEEKS = 2  # een statusverandering binnen dit aantal weken wordt als \'LET OP\' gemarkeerd\r\nEARNINGS_RECENT_DAYS = 7  # hoe recent gerapporteerde cijfers moeten zijn om als \'deze week\' te tellen\r\n\r\n\r\nFAIR_VALUE_THRESHOLD_PCT = 10  # marge rond 0% om ruis te voorkomen (kleine schommelingen rond fair value tellen niet als een \'omslag\')\n\n\ndef _fair_value_bucket(afwijking_pct) -> str:\n    """\n    Bepaalt of een positie momenteel \'cheap\' (duidelijk onder fair value),\n    \'expensive\' (duidelijk erboven), of \'neutral\' (te dicht bij fair value\n    om iets van te zeggen) is -- gebruikt om NIEUWE omslagen te herkennen\n    (bv. cheap -> expensive), i.p.v. elke kleine schommeling rond 0% als\n    een omslag te tellen.\n    """\n    if afwijking_pct is None:\n        return None\n    if afwijking_pct < -FAIR_VALUE_THRESHOLD_PCT:\n        return "cheap"\n    elif afwijking_pct > FAIR_VALUE_THRESHOLD_PCT:\n        return "expensive"\n    else:\n        return "neutral"\n\n\ndef get_upcoming_earnings_date(ticker: str):\n    """\n    Checkt of deze positie AANKOMENDE cijfers heeft binnen de komende 7\n    dagen -- vooruitkijkend, in tegenstelling tot get_earnings_surprise()\n    (die kijkt naar AL gerapporteerde cijfers). Geeft None terug als er\n    geen aankomende cijfers binnen dat venster zijn, of als het niet op\n    te halen is.\n    """\n    try:\n        earnings_dates = yf.Ticker(ticker).get_earnings_dates(limit=8)\n        if earnings_dates is None or earnings_dates.empty:\n            return None\n        today = pd.Timestamp.now(tz=earnings_dates.index.tz).normalize()\n        window_end = today + pd.Timedelta(days=7)\n        future_dates = earnings_dates.index[(earnings_dates.index >= today) & (earnings_dates.index <= window_end)]\n        return future_dates[0] if len(future_dates) > 0 else None\n    except Exception:\n        return None\n\n\ndef check_holding(naam: str, ticker: str):\r\n    # Earnings-verrassing (al gerapporteerd), aankomende earnings (komende\r\n    # 7 dagen), EN fair-value-afwijking zijn allemaal onafhankelijk van of\r\n    # er genoeg historie is voor Supertrend -- altijd proberen op te\r\n    # halen, ook als de technische check hieronder faalt.\r\n    earnings_info = get_earnings_surprise(ticker)\r\n    upcoming_earnings = get_upcoming_earnings_date(ticker)\r\n    fair_value_info = get_fair_value_estimate(ticker)\r\n    fair_value_bucket = _fair_value_bucket(fair_value_info.get("afwijking_pct"))\r\n\r\n    try:\r\n        df = fetch_weekly(ticker)\r\n    except Exception as exc:\r\n        print(f"  {naam} ({ticker}): fout bij ophalen ({exc})")\r\n        return {\r\n            "naam": naam, "ticker": ticker, "status": "ONBEKEND (fout bij ophalen)",\r\n            "sinds": None, "weken_in_trend": None, "recent_gewijzigd": False,\r\n            "prijs": None, "boven_ema20": None, "roic_pct": None, "roic_trend": "onbekend",\r\n            "week_change_pct": None,\r\n            "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n            "earnings_beat": earnings_info["beat"],\r\n            "earnings_date": earnings_info["earnings_date"],\r\n            "upcoming_earnings_date": upcoming_earnings,\r\n            "afwijking_fair_value_pct": fair_value_info.get("afwijking_pct"),\r\n            "fair_value_bucket": fair_value_bucket,\r\n        }\r\n\r\n    min_needed = max(ATR_LENGTH, TREND_FILTER_EMA_LENGTH) + 5\r\n    if df.empty or len(df) < min_needed:\r\n        print(f"  {naam} ({ticker}): te weinig data voor Supertrend (nodig: {min_needed}, "\r\n              f"gekregen: {len(df)})")\r\n        latest_price = round(float(df[\'close\'].iloc[-1]), 2) if not df.empty else None\r\n        week_change_pct = None\r\n        if len(df) >= 2:\r\n            prev_close = float(df["close"].iloc[-2])\r\n            if prev_close:\r\n                week_change_pct = (float(df["close"].iloc[-1]) - prev_close) / prev_close * 100\r\n        return {\r\n            "naam": naam, "ticker": ticker, "status": "ONBEKEND (te weinig historie)",\r\n            "sinds": None, "weken_in_trend": None, "recent_gewijzigd": False,\r\n            "prijs": latest_price, "boven_ema20": None, "roic_pct": None, "roic_trend": "onbekend",\r\n            "week_change_pct": week_change_pct,\r\n            "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n            "earnings_beat": earnings_info["beat"],\r\n            "earnings_date": earnings_info["earnings_date"],\r\n            "upcoming_earnings_date": upcoming_earnings,\r\n            "afwijking_fair_value_pct": fair_value_info.get("afwijking_pct"),\r\n            "fair_value_bucket": fair_value_bucket,\r\n        }\r\n\r\n    st = supertrend(df, length=ATR_LENGTH, multiplier=ATR_MULTIPLIER)\r\n    df = df.copy()\r\n    df["trend_dir"] = st["trend_dir"]\r\n    df["ema_trend"] = ema(df["close"], TREND_FILTER_EMA_LENGTH)\r\n\r\n    current_trend = int(df["trend_dir"].iloc[-1])\r\n    trend_changes = df.index[df["trend_dir"] != df["trend_dir"].shift(1)]\r\n    last_change = trend_changes[-1] if len(trend_changes) > 0 else df.index[0]\r\n    weeks_in_current_trend = len(df.loc[last_change:]) - 1\r\n\r\n    latest_row = df.iloc[-1]\r\n    roic_data = get_roic_data(ticker)\r\n\r\n    prev_close = float(df["close"].iloc[-2])\r\n    week_change_pct = (float(latest_row["close"]) - prev_close) / prev_close * 100 if prev_close else None\r\n\r\n    return {\r\n        "naam": naam,\r\n        "ticker": ticker,\r\n        "status": "BULLISH" if current_trend == 1 else "BEARISH",\r\n        "sinds": last_change.date(),\r\n        "weken_in_trend": weeks_in_current_trend,\r\n        "recent_gewijzigd": weeks_in_current_trend <= RECENT_CHANGE_WEEKS,\r\n        "prijs": round(float(latest_row["close"]), 2),\r\n        "boven_ema20": bool(latest_row["close"] > latest_row["ema_trend"]),\r\n        "roic_pct": round(roic_data["roic"] * 100, 1) if roic_data["roic"] is not None else None,\r\n        "roic_trend": roic_data["roic_trend"],\r\n        "week_change_pct": week_change_pct,\r\n        "earnings_surprise_pct": earnings_info["surprise_pct"],\r\n        "earnings_beat": earnings_info["beat"],\r\n        "earnings_date": earnings_info["earnings_date"],\r\n        "upcoming_earnings_date": upcoming_earnings,\r\n        "afwijking_fair_value_pct": fair_value_info.get("afwijking_pct"),\r\n        "fair_value_bucket": fair_value_bucket,\r\n    }\r\n\r\n\r\ndef build_email_body(df: pd.DataFrame) -> tuple:\r\n    """Bouwt de Portfolio Watch-mail -- zelfde Hesty\'s-stijl als de dagelijkse/wekelijkse signalen-mails."""\r\n    changed = df[df["recent_gewijzigd"]]\r\n\r\n    # --- Beknopt: alleen wat DEZE WEEK daadwerkelijk is veranderd, i.p.v.\r\n    # een volledige, elke-keer-herhalende samenvatting van alles. ---\r\n    from datetime import datetime as _datetime\r\n\r\n    def _is_recent_earnings(earnings_date):\r\n        if earnings_date is None:\r\n            return False\r\n        try:\r\n            ed = earnings_date.date() if hasattr(earnings_date, "date") else earnings_date\r\n            days_since = (_datetime.now().date() - ed).days\r\n            return 0 <= days_since <= EARNINGS_RECENT_DAYS\r\n        except Exception:\r\n            return False\r\n\r\n    earnings_mask = df["earnings_date"].apply(_is_recent_earnings) & df["earnings_surprise_pct"].notna()\r\n    earnings_this_week = df[earnings_mask]\r\n\r\n    upcoming_earnings = df[df["upcoming_earnings_date"].notna()].sort_values("upcoming_earnings_date")\r\n\r\n    # --- Zorgpunten (\'Worth a closer look\'): NIEUWE dalende ROIC, een\r\n    # recente earnings-misser, EN/OF een NIEUWE omslag naar \'expensive\'\r\n    # (duidelijk boven fair value) -- allemaal zaken die je mening over\r\n    # een positie zouden kunnen bijstellen, in tegenstelling tot een\r\n    # neutrale trend-flip of een earnings-beat.\r\n    #\r\n    # \'roic_decline_is_new\'/\'fair_value_crossed_expensive_is_new\' worden\r\n    # door de aanroeper vooraf berekend (via database.get_roic_trend_history())\r\n    # -- vergelijkt de HUIDIGE stand met de LAATST BEKENDE stand van vorige\r\n    # week. Als deze kolommen ontbreken (bv. bij handmatig testen zonder\r\n    # database-koppeling), valt dit terug op het oude gedrag (elke\r\n    # \'dalend\'/\'expensive\' telt mee) i.p.v. te crashen. ---\r\n    has_new_roic_column = "roic_decline_is_new" in df.columns\r\n    has_fair_value_column = "fair_value_crossed_expensive_is_new" in df.columns\r\n\r\n    def _fundamental_reason(row):\r\n        reasons = []\r\n        is_new_decline = row["roic_decline_is_new"] if has_new_roic_column else (row["roic_trend"] == "dalend")\r\n        if is_new_decline:\r\n            reasons.append("ROIC just turned declining year-over-year")\r\n        if earnings_mask.get(row.name, False) and row["earnings_beat"] is False:\r\n            reasons.append(f"missed earnings estimates by {row[\'earnings_surprise_pct\']:+.1f}%")\r\n        is_newly_expensive = (\r\n            row["fair_value_crossed_expensive_is_new"] if has_fair_value_column\r\n            else (row.get("fair_value_bucket") == "expensive")\r\n        )\r\n        if is_newly_expensive:\r\n            reasons.append(f"now trading {row[\'afwijking_fair_value_pct\']:+.0f}% above estimated fair value")\r\n        return " and ".join(reasons)\r\n\r\n    roic_decline_flag = df["roic_decline_is_new"] if has_new_roic_column else (df["roic_trend"] == "dalend")\r\n    fair_value_expensive_flag = (\r\n        df["fair_value_crossed_expensive_is_new"] if has_fair_value_column\r\n        else (df.get("fair_value_bucket") == "expensive" if "fair_value_bucket" in df.columns else False)\r\n    )\r\n    fundamental_mask = roic_decline_flag | (earnings_mask & (df["earnings_beat"] == False)) | fair_value_expensive_flag\r\n    fundamental_concerns = df[fundamental_mask].copy()\r\n    if not fundamental_concerns.empty:\r\n        fundamental_concerns["reason"] = fundamental_concerns.apply(_fundamental_reason, axis=1)\r\n\r\n    # --- Positieve signalen (\'Improving fundamentals\'): NIEUWE stijgende\r\n    # ROIC EN/OF een NIEUWE omslag naar \'cheap\' (duidelijk onder fair\r\n    # value) -- apart van de zorgpunten-sectie gehouden, want een\r\n    # waarschuwings-icoon naast goed nieuws zou verwarrend zijn. ---\r\n    has_new_roic_improve_column = "roic_improvement_is_new" in df.columns\r\n    has_fair_value_cheap_column = "fair_value_crossed_cheap_is_new" in df.columns\r\n\r\n    def _positive_reason(row):\r\n        reasons = []\r\n        is_new_improvement = (\r\n            row["roic_improvement_is_new"] if has_new_roic_improve_column\r\n            else (row["roic_trend"] == "stijgend")\r\n        )\r\n        if is_new_improvement:\r\n            reasons.append("ROIC just turned improving year-over-year")\r\n        is_newly_cheap = (\r\n            row["fair_value_crossed_cheap_is_new"] if has_fair_value_cheap_column\r\n            else (row.get("fair_value_bucket") == "cheap")\r\n        )\r\n        if is_newly_cheap:\r\n            reasons.append(f"now trading {row[\'afwijking_fair_value_pct\']:+.0f}% below estimated fair value")\r\n        return " and ".join(reasons)\r\n\r\n    roic_improve_flag = df["roic_improvement_is_new"] if has_new_roic_improve_column else (df["roic_trend"] == "stijgend")\r\n    fair_value_cheap_flag = (\r\n        df["fair_value_crossed_cheap_is_new"] if has_fair_value_cheap_column\r\n        else (df.get("fair_value_bucket") == "cheap" if "fair_value_bucket" in df.columns else False)\r\n    )\r\n    positive_mask = roic_improve_flag | fair_value_cheap_flag\r\n    positive_signals = df[positive_mask].copy()\r\n    if not positive_signals.empty:\r\n        positive_signals["reason"] = positive_signals.apply(_positive_reason, axis=1)\r\n\r\n    notable_tickers = (\r\n        set(changed["ticker"]) | set(earnings_this_week["ticker"])\r\n        | set(fundamental_concerns["ticker"]) | set(positive_signals["ticker"])\r\n    )\r\n    quiet_positions = df[~df["ticker"].isin(notable_tickers)]\r\n\r\n    # --- Gewogen weekrendement + beste/slechtste positie deze week --\r\n    # gewogen op huidige positiewaarde (shares x prijs), zodat een grote\r\n    # positie logischerwijs zwaarder meetelt dan een kleine.\r\n    df_with_value = df.copy()\r\n    df_with_value["value"] = df_with_value["shares"].fillna(0) * df_with_value["prijs"].fillna(0)\r\n    valid_week = df_with_value[df_with_value["week_change_pct"].notna() & (df_with_value["value"] > 0)]\r\n    portfolio_week_change_pct = None\r\n    if not valid_week.empty and valid_week["value"].sum() > 0:\r\n        portfolio_week_change_pct = (valid_week["week_change_pct"] * valid_week["value"]).sum() / valid_week["value"].sum()\r\n\r\n    best_this_week = worst_this_week = None\r\n    valid_week_moves = df[df["week_change_pct"].notna()]\r\n    if not valid_week_moves.empty:\r\n        best_this_week = valid_week_moves.loc[valid_week_moves["week_change_pct"].idxmax()]\r\n        worst_this_week = valid_week_moves.loc[valid_week_moves["week_change_pct"].idxmin()]\r\n        if best_this_week["ticker"] == worst_this_week["ticker"]:\r\n            worst_this_week = None  # slechts 1 positie met bekende weekbeweging -- niet 2x dezelfde tonen\r\n\r\n    # --- Tekst-versie ---\r\n    text_lines = ["Good morning from Hesty\'s -- here\'s your portfolio watch.", ""]\r\n\r\n    if portfolio_week_change_pct is not None:\r\n        text_lines.append(f"\xf0\x9f\x93\x88 Your portfolio this week: {portfolio_week_change_pct:+.1f}%")\r\n        if best_this_week is not None:\r\n            text_lines.append(f"  Best: {best_this_week[\'naam\']} ({best_this_week[\'ticker\']}) {best_this_week[\'week_change_pct\']:+.1f}%")\r\n        if worst_this_week is not None:\r\n            text_lines.append(f"  Worst: {worst_this_week[\'naam\']} ({worst_this_week[\'ticker\']}) {worst_this_week[\'week_change_pct\']:+.1f}%")\r\n        text_lines.append("")\r\n\r\n    if len(changed) > 0:\r\n        text_lines.append("\xf0\x9f\x94\x84 Trend changes this week:")\r\n        for _, row in changed.iterrows():\r\n            emoji = "\xf0\x9f\x9f\xa2" if row["status"] == "BULLISH" else "\xf0\x9f\x94\xb4"\r\n            text_lines.append(f"  {emoji} {row[\'naam\']} ({row[\'ticker\']}): flipped to {row[\'status\']}")\r\n    else:\r\n        text_lines.append("\xf0\x9f\x94\x84 No trend changes this week.")\r\n    text_lines.append("")\r\n\r\n    if not fundamental_concerns.empty:\r\n        text_lines.append("\xe2\x9a\xa0\xef\xb8\x8f Worth a closer look:")\r\n        for _, row in fundamental_concerns.iterrows():\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {row[\'reason\']}")\r\n        text_lines.append("")\r\n\r\n    if not positive_signals.empty:\r\n        text_lines.append("\xe2\x9c\xa8 Improving fundamentals:")\r\n        for _, row in positive_signals.iterrows():\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {row[\'reason\']}")\r\n        text_lines.append("")\r\n\r\n    if len(earnings_this_week) > 0:\r\n        text_lines.append("\xf0\x9f\x93\x8a Earnings this week:")\r\n        for _, row in earnings_this_week.iterrows():\r\n            beat_txt = "beat" if row["earnings_beat"] else "missed"\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {beat_txt} estimates by {row[\'earnings_surprise_pct\']:+.1f}%")\r\n        text_lines.append("")\r\n\r\n    if len(upcoming_earnings) > 0:\r\n        text_lines.append("\xf0\x9f\x93\x85 Earnings coming up next week:")\r\n        for _, row in upcoming_earnings.iterrows():\r\n            earnings_date_str = row["upcoming_earnings_date"].strftime("%A %Y-%m-%d")\r\n            text_lines.append(f"  - {row[\'naam\']} ({row[\'ticker\']}): {earnings_date_str}")\r\n        text_lines.append("")\r\n\r\n    if len(quiet_positions) > 0:\r\n        quiet_names = ", ".join(quiet_positions["ticker"].tolist())\r\n        text_lines.append(f"\xe2\x9c\x85 No notable changes ({len(quiet_positions)} position(s)): {quiet_names}")\r\n        text_lines.append("")\r\n\r\n    text_lines += [\r\n        "See the full picture under Analyze > Portfolio Overview on the site.",\r\n        "",\r\n        "-- Hesty\'s, your personal investment assistant",\r\n        "",\r\n        "This is a screener, not investment advice.",\r\n    ]\r\n    text_body = "\\n".join(text_lines)\r\n\r\n    # --- HTML-versie: zelfde donkere-header-met-jade-accent-stijl als de\r\n    # andere Hesty\'s-mails, maar nu bewust beknopt: korte secties i.p.v.\r\n    # een volledige tabel + nieuws-dump. ---\r\n    week_summary_html = ""\r\n    if portfolio_week_change_pct is not None:\r\n        week_color = "#0F8F6E" if portfolio_week_change_pct >= 0 else "#C1524A"\r\n        best_worst_bits = []\r\n        if best_this_week is not None:\r\n            best_worst_bits.append(\r\n                f"<div style=\'margin-top:6px;\'>Best: <strong>{best_this_week[\'naam\']} ({best_this_week[\'ticker\']})</strong> "\r\n                f"<span style=\'color:#0F8F6E;\'>{best_this_week[\'week_change_pct\']:+.1f}%</span></div>"\r\n            )\r\n        if worst_this_week is not None:\r\n            best_worst_bits.append(\r\n                f"<div style=\'margin-top:2px;\'>Worst: <strong>{worst_this_week[\'naam\']} ({worst_this_week[\'ticker\']})</strong> "\r\n                f"<span style=\'color:#C1524A;\'>{worst_this_week[\'week_change_pct\']:+.1f}%</span></div>"\r\n            )\r\n        # Best/Worst nu elk in een eigen <div> (blok-elementen, stapelen\r\n        # dus altijd netjes onder elkaar) i.p.v. samengevoegd op 1 regel\r\n        # met een \'&middot;\'-scheidingsteken -- dat brak op smalle\r\n        # mobiele mail-schermen soms lelijk af, met alleen het percentage\r\n        # van \'Worst\' op een eigen regel.\r\n        best_worst_html = (\r\n            f"<div style=\'font-size:13px; color:#5B6472;\'>{\'\'.join(best_worst_bits)}</div>"\r\n            if best_worst_bits else ""\r\n        )\r\n        week_summary_html = f"""\r\n        <div style="background:#F7F9FA; border-radius:8px; padding:14px 16px; margin-bottom:20px;">\r\n            <span style="font-size:14px; color:#5B6472;">\xf0\x9f\x93\x88 Your portfolio this week</span><br/>\r\n            <span style="font-size:22px; font-weight:700; color:{week_color};">{portfolio_week_change_pct:+.1f}%</span>\r\n            {best_worst_html}\r\n        </div>\r\n        """\r\n\r\n    def _flip_row_html(r):\r\n        emoji = "\xf0\x9f\x9f\xa2" if r["status"] == "BULLISH" else "\xf0\x9f\x94\xb4"\r\n        status_color = "#0F8F6E" if r["status"] == "BULLISH" else "#C1524A"\r\n        return (\r\n            f"<li style=\'padding:6px 0;\'>{emoji} <strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"flipped to <span style=\'color:{status_color}; font-weight:600;\'>{r[\'status\']}</span></li>"\r\n        )\r\n\r\n    if len(changed) > 0:\r\n        flips_html = f"<ul style=\'margin:8px 0; padding-left:20px;\'>{\'\'.join(_flip_row_html(r) for _, r in changed.iterrows())}</ul>"\r\n    else:\r\n        flips_html = "<p style=\'color:#5B6472; margin:8px 0;\'>No trend changes this week.</p>"\r\n\r\n    fundamental_html = ""\r\n    if not fundamental_concerns.empty:\r\n        fundamental_items = "".join(\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"<span style=\'color:#C1524A;\'>{r[\'reason\']}</span></li>"\r\n            for _, r in fundamental_concerns.iterrows()\r\n        )\r\n        fundamental_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xe2\x9a\xa0\xef\xb8\x8f Worth a closer look</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{fundamental_items}</ul>"\r\n        )\r\n\r\n    positive_html = ""\r\n    if not positive_signals.empty:\r\n        positive_items = "".join(\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"<span style=\'color:#0F8F6E;\'>{r[\'reason\']}</span></li>"\r\n            for _, r in positive_signals.iterrows()\r\n        )\r\n        positive_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xe2\x9c\xa8 Improving fundamentals</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{positive_items}</ul>"\r\n        )\r\n\r\n    def _earnings_row_html(r):\r\n        beat_txt = "beat" if r["earnings_beat"] else "missed"\r\n        color = "#0F8F6E" if r["earnings_beat"] else "#C1524A"\r\n        return (\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"{beat_txt} estimates by <span style=\'color:{color}; font-weight:600;\'>{r[\'earnings_surprise_pct\']:+.1f}%</span></li>"\r\n        )\r\n\r\n    earnings_section_html = ""\r\n    if len(earnings_this_week) > 0:\r\n        earnings_items = "".join(_earnings_row_html(r) for _, r in earnings_this_week.iterrows())\r\n        earnings_section_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xf0\x9f\x93\x8a Earnings this week</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{earnings_items}</ul>"\r\n        )\r\n\r\n    upcoming_earnings_html = ""\r\n    if len(upcoming_earnings) > 0:\r\n        upcoming_items = "".join(\r\n            f"<li style=\'padding:6px 0;\'><strong style=\'color:#101825;\'>{r[\'naam\']} ({r[\'ticker\']})</strong>: "\r\n            f"{r[\'upcoming_earnings_date\'].strftime(\'%A %Y-%m-%d\')}</li>"\r\n            for _, r in upcoming_earnings.iterrows()\r\n        )\r\n        upcoming_earnings_html = (\r\n            f"<h4 style=\'color:#101825; font-size:15px; margin:20px 0 4px 0;\'>\xf0\x9f\x93\x85 Earnings coming up next week</h4>"\r\n            f"<ul style=\'margin:8px 0; padding-left:20px;\'>{upcoming_items}</ul>"\r\n        )\r\n\r\n    quiet_html = ""\r\n    if len(quiet_positions) > 0:\r\n        quiet_names = ", ".join(quiet_positions["ticker"].tolist())\r\n        quiet_html = (\r\n            f"<p style=\'margin-top:20px; font-size:13px; color:#5B6472;\'>"\r\n            f"\xe2\x9c\x85 No notable changes ({len(quiet_positions)}): {quiet_names}</p>"\r\n        )\r\n\r\n    html_body = f"""\r\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\r\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\r\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Portfolio Watch</div>\r\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">Your positions, checked</div>\r\n        </div>\r\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\r\n            {week_summary_html}\r\n            <h4 style="color:#101825; font-size:15px; margin:0 0 4px 0;">\xf0\x9f\x94\x84 Trend changes this week</h4>\r\n            {flips_html}\r\n            {fundamental_html}\r\n            {positive_html}\r\n            {earnings_section_html}\r\n            {upcoming_earnings_html}\r\n            {quiet_html}\r\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\r\n                See the full picture under\r\n                <a href="https://hestys.streamlit.app/analyze?subview=portfolio" style="color:#1FAE96; font-weight:600; text-decoration:none;">Analyze &gt; Portfolio Overview</a> on the site.\r\n            </p>\r\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\r\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\r\n        </div>\r\n    </div>\r\n    """\r\n    return text_body, html_body\r\n\r\n\r\ndef main() -> None:\r\n    portfolio_holdings = get_current_holdings()\r\n    print(f"Portfolio Watch: {len(portfolio_holdings)} posities checken "\r\n          f"(weekly, ATR-periode {ATR_LENGTH}, multiplier {ATR_MULTIPLIER})...\\n")\r\n\r\n    results = []\r\n    for holding in portfolio_holdings:\r\n        result = check_holding(holding["naam"], holding["ticker"])\r\n        if result:\r\n            result["shares"] = holding.get("shares")\r\n            results.append(result)\r\n            marker = " <-- LET OP, recent gewijzigd" if result["recent_gewijzigd"] else ""\r\n            if result["sinds"] is not None:\r\n                print(f"  {result[\'naam\']}: {result[\'status\']} sinds {result[\'sinds\']} "\r\n                      f"({result[\'weken_in_trend\']} weken){marker}")\r\n            else:\r\n                print(f"  {result[\'naam\']}: {result[\'status\']}")\r\n\r\n    if not results:\r\n        print("\\nGeen enkele positie kon gecheckt worden -- controleer je tickers.")\r\n        return\r\n\r\n    df = pd.DataFrame(results)\r\n    df.to_csv("portfolio_watch.csv", index=False)\r\n\r\n    print(f"\\n=== OVERZICHT ===\\n")\r\n    print(df.to_string(index=False))\r\n\r\n    print("\\nOpgeslagen in \'portfolio_watch.csv\'.")\r\n\r\n    # --- Alleen NIEUWE signalen laten meetellen -- vergelijkt met vorige\r\n    # week\'s bekende stand, i.p.v. elke week opnieuw dezelfde, allang-\r\n    # bekende trend/waardering te melden. ---\r\n    previous_states = get_roic_trend_history(df["ticker"].tolist())\r\n\r\n    def _was_roic_trend(ticker, trend):\r\n        return previous_states.get(ticker, {}).get("roic_trend") == trend\r\n\r\n    def _was_fair_value_bucket(ticker, bucket):\r\n        return previous_states.get(ticker, {}).get("fair_value_bucket") == bucket\r\n\r\n    df["roic_decline_is_new"] = df.apply(\r\n        lambda r: r["roic_trend"] == "dalend" and not _was_roic_trend(r["ticker"], "dalend"), axis=1\r\n    )\r\n    df["roic_improvement_is_new"] = df.apply(\r\n        lambda r: r["roic_trend"] == "stijgend" and not _was_roic_trend(r["ticker"], "stijgend"), axis=1\r\n    )\r\n    df["fair_value_crossed_expensive_is_new"] = df.apply(\r\n        lambda r: r["fair_value_bucket"] == "expensive" and not _was_fair_value_bucket(r["ticker"], "expensive"), axis=1\r\n    )\r\n    df["fair_value_crossed_cheap_is_new"] = df.apply(\r\n        lambda r: r["fair_value_bucket"] == "cheap" and not _was_fair_value_bucket(r["ticker"], "cheap"), axis=1\r\n    )\r\n\r\n    if email_is_configured():\r\n        text_body, html_body = build_email_body(df)\r\n        n_changed = int(df["recent_gewijzigd"].sum())\r\n        n_earnings = int((df["earnings_surprise_pct"].notna()).sum())\r\n        subject_parts = []\r\n        if n_changed > 0:\r\n            subject_parts.append(f"{n_changed} trend change(s)")\r\n        if n_earnings > 0:\r\n            subject_parts.append(f"{n_earnings} earnings update(s)")\r\n        subject = f"Portfolio Watch: {\', \'.join(subject_parts)}" if subject_parts else "Portfolio Watch: no notable changes this week"\r\n        send_email(subject=subject, body_text=text_body, body_html=html_body)\r\n    else:\r\n        print("\\n(E-mail niet verstuurd: nog niet ingesteld in .env.)")\r\n\r\n    # De HUIDIGE stand opslaan als \'vorige week\' voor de volgende run --\r\n    # onafhankelijk van of de mail daadwerkelijk verstuurd werd, want deze\r\n    # week se check heeft sowieso plaatsgevonden.\r\n    current_states = {\r\n        row["ticker"]: {"roic_trend": row["roic_trend"], "fair_value_bucket": row["fair_value_bucket"]}\r\n        for _, row in df.iterrows()\r\n    }\r\n    save_roic_trend_history(current_states)\r\n\r\n\r\nif __name__ == "__main__":\r\n    main()\r\n'

SCREENER_DAILY_CONTENT = b'"""\nDagelijkse variant van screener.py -- zelfde signaal-logica (Supertrend-\nomslag + ROIC + winst-verrassing + fair value + relatieve sterkte), maar\nop DAGELIJKSE candles i.p.v. wekelijkse, met instellingen die daarbij\npassen (kortere periodes). Bedoeld voor swing trades (dagen-weken), naast\nde bestaande wekelijkse screener (voor lange-termijn-overtuigingen).\n\nBewust een APART bestand i.p.v. de bestaande, uitgebreid-afgestelde\nscreener.py aan te passen -- dat voorkomt dat wijzigingen hier de\ngoed-werkende wekelijkse screener zouden kunnen breken. Hergebruikt wel\nalle tijdschaal-onafhankelijke bouwstenen (tickerlijsten, ROIC,\nwinst-verrassing, fair value, nieuws) via import.\n\nGebruik: python screener_daily.py\n"""\nfrom __future__ import annotations\n\nimport pandas as pd\nimport yfinance as yf\n\nfrom macro_events import get_todays_macro_events\n\nfrom indicators import supertrend, ema, volume_ratio\nfrom screener import (\n    FALLBACK_TICKERS, BENCHMARKS, DEFAULT_BENCHMARK,\n    fetch_aex_tickers, fetch_nasdaq100_tickers, fetch_sp500_tickers,\n    fetch_dax_tickers, fetch_cac40_tickers, build_ticker_list,\n    get_benchmark_for_ticker, get_trailing_return_pct, get_prior_trend_duration,\n    get_roic_data, get_earnings_surprise, get_fair_value_estimate,\n)\nfrom emailer import send_email, is_configured as email_is_configured\n\n# --- Instellingen, geschaald voor dagelijkse candles (i.p.v. wekelijkse) ---\nATR_LENGTH = 10\nATR_MULTIPLIER = 3.0\nLOOKBACK_DAYS_FOR_SIGNAL = 2       # hoe \'vers\' een omslag moet zijn (i.p.v. 2 WEKEN bij de wekelijkse variant)\nTREND_FILTER_EMA_LENGTH = 50       # bredere-trend-context (i.p.v. 20 WEKEN)\nYEARS_OF_HISTORY = 2\nBENCHMARK_LOOKBACK_DAYS = 60       # relatieve-sterkte-vergelijkingsperiode (i.p.v. 12 WEKEN)\nVOLUME_AVG_DAYS = 20\nMIN_PRIOR_TREND_DAYS = 15          # zigzag-ruis-filter (i.p.v. 8 WEKEN)\nEARNINGS_RELEVANCE_DAYS = 45       # hoe recent winstcijfers moeten zijn (i.p.v. 8 WEKEN)\n\n\ndef fetch_daily(ticker: str, years: int = YEARS_OF_HISTORY) -> pd.DataFrame:\n    """\n    Haalt dagelijkse OHLCV-data op -- GEEN resampling naar weekly, in\n    tegenstelling tot screener.py.\n\n    Bevat een verstheids-check: yfinance\'s databron loopt soms 1+\n    handelsdag achter op het moment dat deze scan draait (een bekend,\n    terugkerend probleem -- bevestigd via meerdere GitHub-issues over\n    \'laatste dag\'-data die niet klopt). Zonder deze check zou een positie\n    stilzwijgend met verouderde cijfers getoond worden (bv. \'Since: 0d\n    ago\' terwijl het eigenlijk 2 handelsdagen geleden was, met een\n    0,00%-koersverandering die niet klopt omdat de \'omslag\'- en\n    \'huidige\'-koers toevallig dezelfde, verouderde rij zijn).\n\n    Vergelijkt NIET met een vast aantal dagen (dat zou een normale\n    maandagochtend-achterstand tot vrijdag, 3 kalenderdagen, ten onrechte\n    als verdacht bestempelen) -- maar met de VERWACHTE meest recente\n    handelsdag, rekening houdend met het weekend, plus 1 dag speling voor\n    incidentele feestdagen.\n    """\n    df = yf.download(ticker, period=f"{years}y", interval="1d", auto_adjust=True, progress=False)\n    if df.empty:\n        return df\n    if isinstance(df.columns, pd.MultiIndex):\n        df.columns = [c[0].lower() for c in df.columns]\n    else:\n        df.columns = [c.lower() for c in df.columns]\n    df = df[["open", "high", "low", "close", "volume"]]\n    # yfinance geeft soms een \'vandaag\'-rij terug voordat de beurs een\n    # geldige slotkoers heeft (bv. vroeg op de ochtend, vlak na het\n    # openen van de scan) -- die rij heeft dan NaN in \'close\'. Zonder\n    # deze filter zou die NaN als \'prijs_nu\' gebruikt worden, en\n    # (aangezien score ook op de laatste koers steunt) ook de score\n    # zelf NaN maken -- precies wat een \'nan\' overal in de mail geeft.\n    df = df[df["close"].notna()]\n\n    if not df.empty:\n        last_date = df.index[-1]\n        if getattr(last_date, "tz", None) is not None:\n            last_date = last_date.tz_localize(None)\n        today = pd.Timestamp.now().normalize()\n        weekday = today.dayofweek  # maandag=0 ... zondag=6\n        # BEWUST geen ruime buffer op doordeweekse dagen (dinsdag-vrijdag) --\n        # een 1-dags-speling zou precies de waargenomen bug (2 handelsdagen\n        # achterstand) ook goedkeuren, en \'m dus onzichtbaar maken. Alleen\n        # rond maandag iets meer ruimte (voor een mogelijke vrijdag-\n        # feestdag) -- die 3-daagse weekend-sprong is al normaal, dus 1\n        # dag extra dekt een incidentele feestdag zonder de vaste\n        # weekend-sprong zelf te flaggen.\n        if weekday == 0:      # maandag\n            max_days_back = 4\n        elif weekday == 6:    # zondag (draait normaal niet, voor de zekerheid)\n            max_days_back = 3\n        else:                  # dinsdag t/m vrijdag\n            max_days_back = 1\n        oldest_acceptable_date = today - pd.Timedelta(days=max_days_back)\n\n        if last_date < oldest_acceptable_date:\n            days_stale = (today - last_date).days\n            print(f"    (Overgeslagen: laatste data voor {ticker} is {days_stale} dag(en) oud "\n                  f"(laatste koers: {last_date.date()}) -- waarschijnlijk yfinance-vertraging, "\n                  f"niet betrouwbaar genoeg voor vandaag.)")\n            return pd.DataFrame()\n\n    return df\n\n\ndef fetch_benchmark_returns_daily() -> dict:\n    """Haalt voor elke benchmark-index 1x het trailing-rendement op (dagelijkse basis)."""\n    returns = {}\n    for benchmark_ticker in set(list(BENCHMARKS.values()) + [DEFAULT_BENCHMARK]):\n        try:\n            df_bench = fetch_daily(benchmark_ticker)\n            returns[benchmark_ticker] = get_trailing_return_pct(df_bench, BENCHMARK_LOOKBACK_DAYS)\n        except Exception as exc:\n            print(f"Kon benchmark {benchmark_ticker} niet ophalen: {exc}")\n            returns[benchmark_ticker] = None\n    return returns\n\n\ndef compute_score_daily(result: dict) -> float:\n    """\n    Zelfde score-opbouw als screener.py\'s compute_score (0-10, dezelfde\n    gewichten), maar met dag-gebaseerde versheid/relevantie-drempels i.p.v.\n    week-gebaseerde.\n    """\n    freshness_score = max(0.0, (LOOKBACK_DAYS_FOR_SIGNAL - result["dagen_geleden"]) / LOOKBACK_DAYS_FOR_SIGNAL * 1.5)\n\n    if result["roic_pct"] is not None:\n        level_points = min(max(result["roic_pct"], 0), 30) / 30 * 1.0\n        trend_points = 0.5 if result["roic_trend"] == "stijgend" else (-0.5 if result["roic_trend"] == "dalend" else 0)\n        roic_score = max(0.0, min(1.5, level_points + trend_points + 0.5))\n    else:\n        roic_score = 0.75\n\n    if result["relatieve_sterkte"] is not None:\n        clamped = min(max(result["relatieve_sterkte"], -20), 20)\n        rs_score = (clamped + 20) / 40 * 2.5\n    else:\n        rs_score = 1.25\n\n    if result.get("volume_bevestigd") is not None:\n        volume_score = 1.0 if result["volume_bevestigd"] else 0.0\n    else:\n        volume_score = 0.5\n\n    is_recent_enough = (\n        result.get("dagen_sinds_earnings") is not None\n        and result["dagen_sinds_earnings"] <= EARNINGS_RELEVANCE_DAYS\n    )\n    if result.get("earnings_surprise_pct") is not None and is_recent_enough:\n        clamped_surprise = min(max(result["earnings_surprise_pct"], -10), 10)\n        earnings_score = (clamped_surprise + 10) / 20 * 1.5\n    else:\n        earnings_score = 0.75\n\n    if result.get("afwijking_fair_value_pct") is not None:\n        clamped_fv = min(max(result["afwijking_fair_value_pct"], -30), 30)\n        fair_value_score = (30 - clamped_fv) / 60 * 2.0\n    else:\n        fair_value_score = 1.0\n\n    return round(\n        freshness_score + roic_score + rs_score + volume_score + earnings_score + fair_value_score, 2\n    )\n\n\ndef check_ticker_daily(ticker: str, benchmark_returns: dict, df: pd.DataFrame = None):\n    if df is None:\n        try:\n            df = fetch_daily(ticker)\n        except Exception as exc:\n            print(f"  {ticker}: fout bij ophalen ({exc})")\n            return None\n\n    min_needed = max(ATR_LENGTH, TREND_FILTER_EMA_LENGTH) + 5\n    if df.empty or len(df) < min_needed:\n        print(f"  {ticker}: te weinig data (nodig: {min_needed}, gekregen: {len(df)})")\n        return None\n\n    st = supertrend(df, length=ATR_LENGTH, multiplier=ATR_MULTIPLIER)\n    df = df.copy()\n    df["trend_dir"] = st["trend_dir"]\n    df["ema_trend"] = ema(df["close"], TREND_FILTER_EMA_LENGTH)\n    df["volume_ratio"] = volume_ratio(df["volume"], length=VOLUME_AVG_DAYS)\n\n    flips = df.index[(df["trend_dir"] == 1) & (df["trend_dir"].shift(1) == -1)]\n    if len(flips) == 0:\n        return None\n\n    last_flip = flips[-1]\n    days_since_flip = len(df.loc[last_flip:]) - 1\n    if days_since_flip > LOOKBACK_DAYS_FOR_SIGNAL:\n        return None\n\n    prior_trend_days = get_prior_trend_duration(df, last_flip)\n    if prior_trend_days < MIN_PRIOR_TREND_DAYS:\n        return None  # waarschijnlijk zigzag-ruis binnen een al lopende trend\n\n    flip_row = df.loc[last_flip]\n    latest_row = df.iloc[-1]\n\n    benchmark_ticker = get_benchmark_for_ticker(ticker)\n    own_return = get_trailing_return_pct(df, BENCHMARK_LOOKBACK_DAYS)\n    benchmark_return = benchmark_returns.get(benchmark_ticker)\n    relative_strength = (\n        round(own_return - benchmark_return, 2)\n        if own_return is not None and benchmark_return is not None\n        else None\n    )\n\n    volume_confirmed = (\n        bool(flip_row["volume_ratio"] > 1) if pd.notna(flip_row["volume_ratio"]) else None\n    )\n\n    result = {\n        "ticker": ticker,\n        "flip_date": last_flip.date(),\n        "dagen_geleden": days_since_flip,\n        "voorgaande_trend_dagen": prior_trend_days,\n        "prijs_bij_omslag": round(float(flip_row["close"]), 2),\n        "prijs_nu": round(float(latest_row["close"]), 2),\n        "sinds_omslag_pct": round((latest_row["close"] / flip_row["close"] - 1) * 100, 2),\n        "boven_ema": bool(latest_row["close"] > latest_row["ema_trend"]),\n        "benchmark": benchmark_ticker,\n        "relatieve_sterkte": relative_strength,\n        "volume_bevestigd": volume_confirmed,\n    }\n\n    roic_data = get_roic_data(ticker)\n    result["roic_pct"] = round(roic_data["roic"] * 100, 1) if roic_data["roic"] is not None else None\n    result["roic_trend"] = roic_data["roic_trend"]\n\n    earnings_data = get_earnings_surprise(ticker)\n    result["earnings_surprise_pct"] = (\n        round(earnings_data["surprise_pct"], 1) if earnings_data["surprise_pct"] is not None else None\n    )\n    result["earnings_beat"] = earnings_data["beat"]\n    result["earnings_date"] = (\n        earnings_data["earnings_date"].date() if earnings_data["earnings_date"] is not None else None\n    )\n    if earnings_data["earnings_date"] is not None:\n        days_since_earnings = (pd.Timestamp.now(tz=earnings_data["earnings_date"].tz) - earnings_data["earnings_date"]).days\n        result["dagen_sinds_earnings"] = max(0, days_since_earnings)\n    else:\n        result["dagen_sinds_earnings"] = None\n\n    fair_value_data = get_fair_value_estimate(ticker)\n    result["fair_value"] = fair_value_data["fair_value"]\n    result["afwijking_fair_value_pct"] = fair_value_data["afwijking_pct"]\n\n    result["score"] = compute_score_daily(result)\n\n    return result\n\n\ndef _get_macro_teaser_text() -> str:\n    """\n    Geeft 1 korte teaser-regel terug als er vandaag een macro-event is\n    (CPI/FOMC/ECB), anders None -- bewust maar 1 regel, alleen op de\n    dagen dat het er toe doet, geen volledige kalender (dat zou de mail\n    te vol maken en de prikkel om naar de site te gaan verminderen).\n    """\n    events = get_todays_macro_events(max_items=1)\n    if not events:\n        return None\n    e = events[0]\n    return f"Also today: {e[\'name\']} ({e[\'time\']})"\n\n\ndef build_no_signals_email_daily(name: str = None) -> tuple:\n    """Korte, warme mail voor een dag zonder signalen -- houdt het dagelijkse contactmoment in stand."""\n    greeting = f"Good morning, {name}" if name else "Good morning"\n    macro_teaser = _get_macro_teaser_text()\n    macro_line_text = f"\\n{macro_teaser}\\n" if macro_teaser else ""\n    macro_line_html = (\n        f\'<p style="margin-top:12px; font-size:13px; color:#1FAE96; font-weight:600;">\xf0\x9f\x93\x85 {macro_teaser}</p>\'\n        if macro_teaser else ""\n    )\n\n    text_body = (\n        f"{greeting} from Hesty\'s\\n\\n"\n        "No bullish flips showed up on today\'s scan -- a quiet day on that front.\\n"\n        f"{macro_line_text}\\n"\n        "Check Discover for sector/theme rotation and earnings surprises, Today for macro events "\n        "and yesterday\'s biggest movers, or Analyse for your own portfolio.\\n\\n"\n        "-- Hesty\'s, your personal investment assistant\\n\\n"\n        "This is a screener, not investment advice."\n    )\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Daily</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">{greeting}</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            <p style="font-size:15px; color:#101825; line-height:1.5; margin-top:0;">\n                No bullish flips showed up on today\'s scan -- a quiet day on that front.\n            </p>\n            {macro_line_html}\n            <p style="margin-top:16px; font-size:14px; color:#5B6472; line-height:1.5;">\n                Check <a href="https://hestys.streamlit.app/discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a>\n                for sector/theme rotation and earnings surprises,\n                <a href="https://hestys.streamlit.app/today" style="color:#1FAE96; font-weight:600; text-decoration:none;">Today</a>\n                for macro events and yesterday\'s biggest movers, or\n                <a href="https://hestys.streamlit.app/analyze" style="color:#1FAE96; font-weight:600; text-decoration:none;">Analyse</a> for your own portfolio.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef build_email_body_daily(df_hits: pd.DataFrame, name: str = None) -> tuple:\n    """\n    Bouwt de dagelijkse mail -- zakelijk maar met een eigen stem: een korte,\n    op de data gebaseerde toelichting (geen hype, geen giswerk) vooraf, dan\n    de tabel, en een korte, herkenbare afsluiting namens Hesty\'s.\n\n    \'name\' (optioneel): voor een persoonlijke aanhef (\'Good morning, [naam]\')\n    -- alleen bekend bij ingelogde gebruikers (via user_identity), niet bij\n    de niet-ingelogde e-mail-opt-in-abonnees, die krijgen de neutrale versie.\n    """\n    n = len(df_hits)\n    top_pick = df_hits.iloc[0]  # df_hits is al gesorteerd op score (hoog naar laag)\n    greeting = f"Good morning, {name}" if name else "Good morning"\n\n    intro_line = (\n        f"{n} stock{\'s\' if n != 1 else \'\'} just flipped bullish on today\'s scan. "\n        f"{top_pick[\'ticker\']} leads with the highest score ({top_pick[\'score\']})."\n    )\n    macro_teaser = _get_macro_teaser_text()\n\n    # --- Tekst-versie ---\n    text_lines = [\n        f"{greeting} from Hesty\'s",\n        "",\n        intro_line,\n    ]\n    if macro_teaser:\n        text_lines.append(macro_teaser)\n    text_lines += [\n        "",\n        "Today\'s signals (highest score first):",\n    ]\n    for _, row in df_hits.iterrows():\n        text_lines.append(\n            f"- [{row[\'score\']}] {row[\'ticker\']} (https://finance.yahoo.com/quote/{row[\'ticker\']}): "\n            f"flipped {row[\'dagen_geleden\']} day(s) ago after {row[\'voorgaande_trend_dagen\']} days bearish -- "\n            f"{row[\'prijs_bij_omslag\']} -> {row[\'prijs_nu\']} ({row[\'sinds_omslag_pct\']:+.2f}%)"\n        )\n    text_lines += [\n        "",\n        "See sector/theme rotation and earnings surprises under Discover on the site, "\n        "or check Today for macro events and yesterday\'s biggest movers.",\n        "",\n        "-- Hesty\'s, your personal investment assistant",\n        "",\n        "This is a screener, not investment advice.",\n    ]\n    text_body = "\\n".join(text_lines)\n\n    # --- HTML-versie: lichte achtergrond (betrouwbaarder in e-mail-clients\n    # dan een donkere), met de merk-kleur (jade) als accent ---\n    rows_html = "".join(\n        f"""<tr style="border-bottom:1px solid #E5E8EC;">\n            <td style="padding:10px 8px;font-weight:700;color:#101825;">{r[\'score\']}</td>\n            <td style="padding:10px 8px;font-weight:600;">\n                <a href="https://finance.yahoo.com/quote/{r[\'ticker\']}" style="color:#1FAE96; text-decoration:none;">{r[\'ticker\']}</a>\n            </td>\n            <td style="padding:10px 8px;color:#5B6472;">{r[\'flip_date\']}</td>\n            <td style="padding:10px 8px;color:#5B6472;">{r[\'dagen_geleden\']}d ago</td>\n            <td style="padding:10px 8px;color:#5B6472;">{r[\'prijs_bij_omslag\']} &rarr; {r[\'prijs_nu\']}</td>\n            <td style="padding:10px 8px;font-weight:600;color:{\'#0F8F6E\' if r[\'sinds_omslag_pct\'] >= 0 else \'#C1524A\'};">{r[\'sinds_omslag_pct\']:+.2f}%</td>\n        </tr>"""\n        for _, r in df_hits.iterrows()\n    )\n\n    macro_line_html = (\n        f\'<p style="margin-top:8px; font-size:13px; color:#1FAE96; font-weight:600;">\xf0\x9f\x93\x85 {macro_teaser}</p>\'\n        if macro_teaser else ""\n    )\n\n    html_body = f"""\n    <div style="font-family: -apple-system, \'Segoe UI\', Roboto, Arial, sans-serif; max-width: 600px; margin: 0 auto; background:#ffffff;">\n        <div style="background:#101825; padding: 28px 24px; border-radius: 12px 12px 0 0;">\n            <div style="color:#1FAE96; font-size:13px; font-weight:600; letter-spacing:1px; text-transform:uppercase;">Hesty\'s Daily</div>\n            <div style="color:#EAEDF1; font-size:22px; font-weight:700; margin-top:4px;">{greeting}</div>\n        </div>\n        <div style="padding: 24px; border: 1px solid #E5E8EC; border-top: none; border-radius: 0 0 12px 12px;">\n            <p style="font-size:15px; color:#101825; line-height:1.5; margin-top:0;">{intro_line}</p>\n            {macro_line_html}\n            <table style="width:100%; border-collapse:collapse; margin-top:16px;">\n                <tr style="border-bottom:2px solid #101825;">\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Score</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Ticker</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Flip Date</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Since</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Price</th>\n                    <th style="text-align:left; padding:8px; font-size:11px; color:#5B6472; text-transform:uppercase;">Change</th>\n                </tr>\n                {rows_html}\n            </table>\n            <p style="margin-top:20px; font-size:14px; color:#5B6472; line-height:1.5;">\n                Want sector/theme rotation and earnings surprises too? Check\n                <a href="https://hestys.streamlit.app/discover" style="color:#1FAE96; font-weight:600; text-decoration:none;">Discover</a> on the site,\n                or see <a href="https://hestys.streamlit.app/today" style="color:#1FAE96; font-weight:600; text-decoration:none;">Today</a>\n                for macro events and yesterday\'s biggest movers.\n            </p>\n            <p style="margin-top:24px; font-size:14px; color:#101825; font-weight:600;">&mdash; Hesty\'s, your personal investment assistant</p>\n            <p style="margin-top:16px; font-size:12px; color:#9AA1AC; font-style:italic;">This is a screener, not investment advice.</p>\n        </div>\n    </div>\n    """\n    return text_body, html_body\n\n\ndef main(send_own_email: bool = True) -> None:\n    tickers = build_ticker_list()\n\n    print("Fetching benchmark returns (for relative strength)...")\n    benchmark_returns = fetch_benchmark_returns_daily()\n\n    print(f"\\nScreening {len(tickers)} tickers for recent bullish Supertrend flips "\n          f"(daily, ATR length {ATR_LENGTH}, multiplier {ATR_MULTIPLIER})...\\n")\n\n    hits = []\n    movers = []\n    for ticker in tickers:\n        try:\n            df = fetch_daily(ticker)\n        except Exception as exc:\n            print(f"  {ticker}: fout bij ophalen ({exc})")\n            continue\n\n        # Dag-op-dag-verandering, voor \'top movers\' -- hergebruikt dezelfde\n        # opgehaalde data als de signaal-check hieronder, dus GEEN extra\n        # API-aanroepen nodig.\n        if not df.empty and len(df) >= 2:\n            try:\n                day_change = (df["close"].iloc[-1] / df["close"].iloc[-2] - 1) * 100\n                movers.append({"ticker": ticker, "change_pct": round(day_change, 2)})\n            except Exception:\n                pass\n\n        result = check_ticker_daily(ticker, benchmark_returns, df=df)\n        if result:\n            hits.append(result)\n            print(f"  {ticker}: SIGNAL ({result[\'dagen_geleden\']} day(s) ago, score {result[\'score\']})")\n        else:\n            print(f"  {ticker}: no recent signal")\n\n    if movers:\n        df_movers = pd.DataFrame(movers).sort_values("change_pct", ascending=False)\n        df_movers.to_csv("top_movers.csv", index=False)\n        print(f"\\nSaved {len(df_movers)} tickers\' daily change to \'top_movers.csv\'.")\n\n    if not hits:\n        print("\\nNo signals today.")\n        if send_own_email and email_is_configured():\n            send_email(subject="Daily screener: no signals today", body_text="No signals found today.")\n        return\n\n    df_hits = pd.DataFrame(hits)\n    df_hits.sort_values("score", ascending=False, inplace=True)\n\n    print(f"\\n=== {len(hits)} SIGNALS FOUND ===\\n")\n    print(df_hits.to_string(index=False))\n\n    df_hits.to_csv("supertrend_signals_daily.csv", index=False)\n    print("\\nSaved to \'supertrend_signals_daily.csv\'.")\n\n    if send_own_email and email_is_configured():\n        text_body, html_body = build_email_body_daily(df_hits)\n        send_email(subject=f"Daily screener: {len(hits)} new signals", body_text=text_body, body_html=html_body)\n\n\nif __name__ == "__main__":\n    main()\n'

DAILY_EMAIL_DISPATCH_CONTENT = b'"""\r\nVerstuurt de dagelijkse screener-mail aan gebruikers, per regio getimed\r\n(zodat iedereen \'m rond hun eigen ochtend krijgt, i.p.v. 1 vast tijdstip\r\nvoor iedereen). Leest de AL bestaande CSV (van de ochtend-scan via\r\ndaily_batch.py) -- doet zelf GEEN nieuwe scan, dat zou zonde van de tijd\r\nen API-aanroepen zijn als dit 3x per dag draait (1x per regio).\r\n\r\nBedoeld om te draaien via GitHub Actions (dus GEEN Streamlit-context --\r\nleest configuratie via omgevingsvariabelen).\r\n\r\nBenodigde omgevingsvariabelen: SUPABASE_URL, SUPABASE_ANON_KEY,\r\nEMAIL_SMTP_SERVER, EMAIL_SMTP_PORT, EMAIL_ADDRESS, EMAIL_APP_PASSWORD\r\n\r\nGebruik: python daily_email_dispatch.py <regio>\r\nwaarbij <regio> een van: EU, US_East, US_West\r\n"""\r\nfrom __future__ import annotations\r\n\r\nimport os\r\nimport sys\r\n\r\nimport pandas as pd\r\nfrom dotenv import load_dotenv\r\nfrom supabase import create_client\r\n\r\nload_dotenv()\r\n\r\nimport screener_daily\r\nfrom emailer import send_email\r\nfrom user_hashing import hash_email\r\n\r\nVALID_REGIONS = ["EU", "US_East", "US_West"]\r\n\r\n\r\ndef get_supabase_client():\r\n    url = os.environ["SUPABASE_URL"]\r\n    key = os.environ["SUPABASE_ANON_KEY"]\r\n    return create_client(url, key)\r\n\r\n\r\ndef get_all_preferences() -> dict:\r\n    """Geeft de e-mail-voorkeuren van ALLE gebruikers terug (sleutel = gehasht e-mailadres)."""\r\n    client = get_supabase_client()\r\n    response = client.table("user_preferences").select("*").execute()\r\n    return {row["user_email"]: row for row in response.data}\r\n\r\n\r\ndef get_real_email_and_name(email_hash: str) -> tuple:\r\n    """\r\n    Zoekt het echte, verstuurbare e-mailadres \xc3\x89N de naam op bij een hash --\r\n    de naam is nodig voor de persoonlijke aanhef (\'Good morning, [naam]\').\r\n    """\r\n    client = get_supabase_client()\r\n    response = client.table("user_identity").select("email, name").eq("email_hash", email_hash).execute()\r\n    if response.data:\r\n        return response.data[0]["email"], response.data[0].get("name")\r\n    return None, None\r\n\r\n\r\ndef get_confirmed_email_subscribers(region: str) -> list:\r\n    """Geeft alle BEVESTIGDE, niet-ingelogde abonnees voor deze regio terug (email + unsubscribe_token)."""\r\n    client = get_supabase_client()\r\n    response = (\r\n        client.table("email_subscribers")\r\n        .select("email, unsubscribe_token")\r\n        .eq("email_region", region)\r\n        .eq("confirmed", True)\r\n        .execute()\r\n    )\r\n    return response.data or []\r\n\r\n\r\ndef _append_unsubscribe_footer(text_body: str, html_body: str, unsubscribe_token: str) -> tuple:\r\n    """\r\n    Voegt een persoonlijke uitschrijflink toe -- alleen voor niet-\r\n    ingelogde abonnees (login-gekoppelde gebruikers beheren hun\r\n    voorkeur via Settings, die hebben geen los token nodig).\r\n    """\r\n    unsubscribe_url = f"https://hestys.streamlit.app/unsubscribe?token={unsubscribe_token}"\r\n    text_with_footer = text_body + f"\\n\\nUnsubscribe: {unsubscribe_url}"\r\n    html_with_footer = html_body + (\r\n        f\'<p style="max-width:600px; margin:12px auto 0 auto; text-align:center; \'\r\n        f\'font-size:11px; color:#9AA1AC;">\'\r\n        f\'<a href="{unsubscribe_url}" style="color:#9AA1AC;">Unsubscribe</a></p>\'\r\n    )\r\n    return text_with_footer, html_with_footer\r\n\r\n\r\ndef run_daily_screener_emails_for_region(preferences: dict, region: str) -> None:\r\n    """\r\n    Stuurt de dagelijkse screener-mail naar gebruikers die in DEZE regio\r\n    zitten en opt-in zijn -- combineert 2 bronnen (login-gekoppelde\r\n    voorkeuren EN niet-ingelogde abonnees), en dedupliceert op e-mailadres\r\n    zodat iemand die toevallig via BEIDE routes is aangemeld niet 2x mail\r\n    krijgt. Bij overlap wint de login-gekoppelde versie (geen los\r\n    uitschrijf-token nodig, die persoon beheert het via Settings).\r\n\r\n    De mail wordt per ontvanger apart opgebouwd (niet 1x gedeeld) --\r\n    ingelogde gebruikers krijgen een persoonlijke aanhef (\'Good morning,\r\n    [naam]\'), niet-ingelogde abonnees (geen naam bekend) de neutrale versie.\r\n    """\r\n    print(f"\\n=== Dagelijkse screener-mails versturen voor regio: {region} ===")\r\n\r\n    # --- Bron 1: login-gekoppelde gebruikers ---\r\n    opted_in_hashes = [\r\n        email_hash for email_hash, prefs in preferences.items()\r\n        if prefs.get("wants_daily_email") and prefs.get("email_region", "EU") == region\r\n    ]\r\n    logged_in_recipients = {}  # lowercased e-mail -> {"name": ..., "unsubscribe_token": None}\r\n    for email_hash in opted_in_hashes:\r\n        real_email, name = get_real_email_and_name(email_hash)\r\n        if real_email:\r\n            logged_in_recipients[real_email.strip().lower()] = {"name": name, "unsubscribe_token": None}\r\n        else:\r\n            print(f"  Kon geen e-mailadres vinden voor hash {email_hash[:12]}... -- overgeslagen.")\r\n\r\n    # --- Bron 2: niet-ingelogde, bevestigde abonnees (geen naam bekend) ---\r\n    no_login_subs = get_confirmed_email_subscribers(region)\r\n    no_login_recipients = {\r\n        sub["email"].strip().lower(): {"name": None, "unsubscribe_token": sub["unsubscribe_token"]}\r\n        for sub in no_login_subs\r\n    }\r\n\r\n    # --- Dedupliceren: bij overlap wint de login-gekoppelde versie (heeft een naam, geen token) ---\r\n    all_recipients = {**no_login_recipients, **logged_in_recipients}\r\n    print(f"{len(logged_in_recipients)} ingelogde gebruiker(s), {len(no_login_recipients)} niet-ingelogde "\r\n          f"abonnee(s) in regio {region} -- {len(all_recipients)} unieke ontvanger(s) na deduplicatie.")\r\n\r\n    if not all_recipients:\r\n        return\r\n\r\n    if not os.path.exists("supertrend_signals_daily.csv"):\r\n        print("Geen supertrend_signals_daily.csv gevonden -- kan geen mail versturen.")\r\n        return\r\n\r\n    df_hits = pd.read_csv("supertrend_signals_daily.csv")\r\n    has_signals = not df_hits.empty\r\n    subject = f"Hesty\'s Daily: {len(df_hits)} new signal(s) today" if has_signals else "Hesty\'s Daily: a quiet day, no new signals"\r\n\r\n    for email, info in all_recipients.items():\r\n        if has_signals:\r\n            text_body, html_body = screener_daily.build_email_body_daily(df_hits, name=info["name"])\r\n        else:\r\n            text_body, html_body = screener_daily.build_no_signals_email_daily(name=info["name"])\r\n        if info["unsubscribe_token"]:\r\n            text_body, html_body = _append_unsubscribe_footer(text_body, html_body, info["unsubscribe_token"])\r\n        send_email(subject=subject, body_text=text_body, body_html=html_body, to_email=email)\r\n\r\n\r\nif __name__ == "__main__":\r\n    if len(sys.argv) < 2 or sys.argv[1] not in VALID_REGIONS:\r\n        print(f"Gebruik: python daily_email_dispatch.py <regio>, waarbij <regio> een van {VALID_REGIONS} is.")\r\n        sys.exit(1)\r\n\r\n    target_region = sys.argv[1]\r\n    all_preferences = get_all_preferences()\r\n    run_daily_screener_emails_for_region(all_preferences, target_region)\r\n    print("\\nKlaar.")\r\n'

with open("weekly_batch.py", "wb") as f:
    f.write(WEEKLY_BATCH_CONTENT)
with open("portfolio_watch.py", "wb") as f:
    f.write(PORTFOLIO_WATCH_CONTENT)
with open("screener_daily.py", "wb") as f:
    f.write(SCREENER_DAILY_CONTENT)
with open("daily_email_dispatch.py", "wb") as f:
    f.write(DAILY_EMAIL_DISPATCH_CONTENT)
print("Weggeschreven: weekly_batch.py, portfolio_watch.py, screener_daily.py, daily_email_dispatch.py")
print("git add .")
print('git commit -m "Nav refactor step B3 (final): update email links in 4 external batch scripts"')
